<header><h1 id="sun-settings-title"><?php esc_html_e('Notification settings','sabri-unified-notifications');?></h1><p><?php esc_html_e('Choose channels, quiet hours, digest frequency and explicit subscriptions. Essential security, safety and system notices cannot be disabled by an ordinary subscription.','sabri-unified-notifications');?></p></header>
<?php foreach($grouped as $category=>$rows): ?><fieldset class="sun-settings__group"><legend><?php echo esc_html(ucwords(str_replace('_',' ',$category)));?></legend><?php foreach($rows as $row): ?><form class="sun-pref" data-sun-preference><input type="hidden" name="category" value="<?php echo esc_attr($row['category']);?>"><input type="hidden" name="channel" value="<?php echo esc_attr($row['channel']);?>"><input type="hidden" name="version" value="<?php echo esc_attr($row['version']);?>"><label><input type="checkbox" name="enabled" value="1" <?php checked($row['enabled']);?> <?php disabled(!empty($row['essential'])&&'in_app'===$row['channel']);?>> <strong><?php echo esc_html(strtoupper($row['channel']));?></strong></label><label><?php esc_html_e('Digest','sabri-unified-notifications');?><select name="digest_frequency" <?php disabled(!empty($row['essential']));?>><option value="immediate" <?php selected($row['digest_frequency'],'immediate');?>><?php esc_html_e('Immediate','sabri-unified-notifications');?></option><option value="daily" <?php selected($row['digest_frequency'],'daily');?>><?php esc_html_e('Daily','sabri-unified-notifications');?></option><option value="weekly" <?php selected($row['digest_frequency'],'weekly');?>><?php esc_html_e('Weekly','sabri-unified-notifications');?></option></select></label><label><input type="checkbox" name="quiet_enabled" value="1" <?php checked($row['quiet_enabled']);?> <?php disabled(!empty($row['essential']));?>> <?php esc_html_e('Quiet hours','sabri-unified-notifications');?></label><input type="time" name="quiet_start" value="<?php echo esc_attr(substr((string)$row['quiet_start'],0,5));?>"><input type="time" name="quiet_end" value="<?php echo esc_attr(substr((string)$row['quiet_end'],0,5));?>"><input type="text" name="timezone" value="<?php echo esc_attr($row['timezone']);?>" aria-label="<?php esc_attr_e('Timezone','sabri-unified-notifications');?>"><button class="sun-button" type="submit"><?php esc_html_e('Save','sabri-unified-notifications');?></button></form><?php endforeach;?></fieldset><?php endforeach;?>
