tifications');?></button></form><?php endforeach;?></div><?php endif; ?><details class="sun-subscription-add"><summary><?php esc_html_e('Add a subscription manually','sabri-unified-notifications');?></summary><form class="sun-subscription" data-sun-subscription><label><?php esc_html_e('Type','sabri-unified-notifications');?><select name="scope_type"><?php foreach($scope_types as $scope_type): ?><option value="<?php echo esc_attr($scope_type);?>"><?php echo esc_html(ucfirst($scope_type));?></option><?php endforeach;?></select></label><label><?php esc_html_e('Source identifier','sabri-unified-notifications');?><input type="text" name="scope_id" maxlength="191" required></label><label><input type="checkbox" name="enabled" value="1" checked> <?php esc_html_e('Enabled','sabri-unified-notifications');?></label><label><?php esc_html_e('Frequency','sabri-unified-notifications');?><select name="frequency"><?php foreach($frequencies as $frequency): ?><option value="<?php echo esc_attr($frequency);?>"><?php echo esc_html(ucfirst($frequency));?></option><?php endforeach;?></select></label><button class="sun-button" type="submit"><?php esc_html_e('Add','sabri-unified-notifications');?></button></form></details></section>
